import React, { useState, useEffect } from 'react';

const API_BASE = 'http://127.0.0.1:8000';

function App() {
  const [task, setTask] = useState('');
  const [result, setResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadHistory();
  }, []);

  const loadHistory = async () => {
    try {
      const response = await fetch(`${API_BASE}/tasks`);
      const data = await response.json();
      setHistory(data);
    } catch (error) {
      console.log(error);
    }
  };

  const submitTask = async (e) => {
    e.preventDefault();

    if (!task.trim()) {
      return;
    }

    setLoading(true);

    try {
      const response = await fetch(`${API_BASE}/tasks`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          task: task
        })
      });

      const data = await response.json();

      setResult(data);
      setTask('');

      loadHistory();
    } catch (error) {
      alert('Backend server not running');
    }

    setLoading(false);
  };

  return (
    <div
      style={{
        padding: '20px',
        fontFamily: 'Arial',
        maxWidth: '800px',
        margin: '0 auto'
      }}
    >
      <h1>Simple Agent Task App</h1>

      <form onSubmit={submitTask}>
        <textarea
          rows='4'
          placeholder='Enter task here'
          value={task}
          onChange={(e) => setTask(e.target.value)}
          style={{
            width: '100%',
            padding: '10px',
            fontFamily: 'Arial'
          }}
        />
        <button type='submit' disabled={loading} style={{ marginTop: '10px', padding: '10px 20px' }}>
          {loading ? 'Loading...' : 'Submit Task'}
        </button>
      </form>

      {result && (
        <div style={{ marginTop: '20px', padding: '10px', border: '1px solid #ccc', borderRadius: '4px' }}>
          <h2>Result:</h2>
          <p>{result.result}</p>
        </div>
      )}

      <div style={{ marginTop: '30px' }}>
        <h2>History:</h2>
        {history.map((item, index) => (
          <div key={index} style={{ padding: '10px', marginBottom: '10px', border: '1px solid #ddd', borderRadius: '4px' }}>
            <p><strong>Task:</strong> {item.task}</p>
            <p><strong>Result:</strong> {item.result}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
